; The dwarf's cave and the hillside outside it (prototype map).
; Format is documented in dist/maps/README.md.

tileset assets/tileset.png

;    char  index  collision  name
tile .     0      walk       cave_floor
tile #     1      solid      cave_wall
tile ,     2      walk       grass
tile "     3      walk       grass_flowers
tile :     4      walk       dirt_path
tile ~     5      solid      water
tile T     6      solid      tree
tile o     7      solid      rock
tile =     8      walk       cave_mouth
tile ^     9      solid      cliff

; where the dwarf starts (column, row), counting from 0 at the top-left
spawn 8 5

